<script setup>
import {computed,onMounted,ref} from 'vue';
import {api} from './api';
import SearchableSelect from './SearchableSelect.vue';
import QuestionContent from './QuestionContent.vue';
import MathText from './MathText.vue';
const emit=defineEmits(['edit']);
const courses=ref([]),papers=ref([]),course=ref(''),paper=ref(''),rows=ref([]),detail=ref(null),guide=ref(null),settings=ref({featured:false,allow_ads:false}),deployment=ref(null),after=ref(0),next=ref(0),more=ref(false),scanned=ref(0),busy=ref(false),error=ref(''),notice=ref(''),checks=ref({}),includeAll=ref(false);
const fields=[['introduction','Introduction'],['topics','Revision topics'],['prerequisites','Useful prior knowledge'],['mistakes','Common mistakes'],['practice','How to practise']];
const labels={source:'Compared question, course and section with the original PDF',calculation:'Independently checked the calculation / reasoning and source answer key',options:'Checked every applicable option explanation (or verified numerical answer)',formatting:'Previewed LaTeX, tables and diagrams on this version'};
const courseOptions=computed(()=>courses.value.map(c=>({value:c.id,label:c.name})));
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function scope(){rows.value=[];detail.value=null;after.value=0;next.value=0;more.value=false;paper.value='';guide.value=null;papers.value=[];if(course.value){const [p,g]=await Promise.all([api('/admin/ai-solutions/summary?course_id='+course.value),api('/admin/content-quality/courses/'+course.value)]);papers.value=p.papers;guide.value=g.guide}}
async function selectPaper(){rows.value=[];detail.value=null;after.value=0;next.value=0;if(paper.value)settings.value=await api('/admin/content-quality/papers/'+paper.value)}
async function scan(reset=false){if(reset)after.value=0;else after.value=next.value;const d=await api('/admin/content-quality/scan?'+new URLSearchParams({course_id:course.value,paper_id:paper.value,after:after.value,all:includeAll.value?'1':'0'}));rows.value=d.items;scanned.value=d.scanned;next.value=d.next_after;more.value=d.has_more;detail.value=null}
async function inspect(row){detail.value=await api('/admin/content-quality/questions/'+row.id);checks.value={};detail.value.id=row.id}
async function reviewed(){await api('/admin/content-quality/questions/'+detail.value.id+'/review',{method:'POST',body:{fingerprint:detail.value.fingerprint,checks:checks.value}});notice.value='Review recorded for this content version. Future question or solution edits require a new review.';detail.value=null;await scan(true)}
async function visibility(row){const d=await api('/admin/questions/'+row.id);await api('/admin/questions/'+row.id+'/visibility',{method:'POST',body:{updated_at:d.updated_at,hidden:row.status!=='HIDDEN'}});row.status=row.status==='HIDDEN'?'AVAILABLE':'HIDDEN';notice.value='Visibility updated. No source content was deleted.'}
async function saveGuide(){await api('/admin/content-quality/courses/'+course.value,{method:'PUT',body:guide.value});notice.value='Course guide saved.'}
async function saveSettings(){await api('/admin/content-quality/papers/'+paper.value,{method:'PUT',body:settings.value});notice.value='Saved. Featuring requires a current published solution; ads additionally require full coverage, current reviews and consent configuration.'}
onMounted(()=>run(async()=>{const [c,d]=await Promise.all([api('/catalog'),api('/admin/content-quality/deployment')]);courses.value=c.courses;deployment.value=d}));
</script>
<template><section class="panel quality-panel"><h2>Content Quality</h2><p>Scan up to 200 questions at a time. Flags are suggestions: compare the original PDF before hiding or editing. A checklist records your review; it does not automatically prove an answer correct.</p><p role="alert" v-if="error" class="alert alert-danger">{{error}}</p><p role="status" v-if="notice" class="alert alert-success">{{notice}}</p><p v-if="busy" role="status">Working…</p>
<details v-if="deployment"><summary>Deployment identity</summary><dl><template v-for="key in ['public_origin','service_id','repository','branch','commit','app_asset']" :key="key"><dt>{{key}}</dt><dd>{{deployment[key]}}</dd></template></dl><p>{{deployment.note}}</p></details>
<fieldset :disabled="busy" class="quality-filters"><label>Course<SearchableSelect v-model="course" :options="courseOptions" placeholder="All courses" search-placeholder="Search courses…" @change="run(scope)"/></label><label>Paper<select v-model="paper" @change="run(selectPaper)"><option value="">All papers in scope</option><option v-for="p in papers" :key="p.id" :value="p.id">{{p.exam}} · {{p.term}} · {{p.name}}</option></select></label></fieldset>
<details v-if="guide" class="my-3"><summary>Edit this course’s original revision guide</summary><p>Suggested text is revision guidance, not an official syllabus. Edit for your course before publishing. An unpublished saved guide stays private.</p><form @submit.prevent="run(saveGuide)"><label v-for="[key,label] in fields" :key="key">{{label}}<textarea v-model="guide[key]" rows="3" maxlength="6000" :disabled="busy"/></label><label><input type="checkbox" v-model="guide.published" :disabled="busy"> Publish guide</label><button class="btn btn-primary" :disabled="busy">Save guide</button><a :href="'/study/courses/'+course" target="_blank" rel="noopener">Preview course page</a></form></details>
<details v-if="paper"><summary>Featured paper and advertising</summary><label><input type="checkbox" v-model="settings.featured" :disabled="busy"> Feature this paper on Home / Featured Study</label><label><input type="checkbox" v-model="settings.allow_ads" :disabled="busy"> Allow manual study-page ad after all eligibility checks pass</label><button class="btn btn-primary" :disabled="busy" @click="run(saveSettings)">Save paper settings</button></details>
<div class="quality-actions"><label><input type="checkbox" v-model="includeAll" :disabled="busy"> Include questions without detected flags</label><button class="btn btn-primary" :disabled="busy" @click="run(()=>scan(true))">Scan from beginning</button><button class="btn btn-light" :disabled="busy||!more" @click="run(()=>scan())">Scan next 200</button></div><p v-if="scanned">{{scanned}} scanned in this batch · {{rows.length}} flagged or awaiting review{{more?' · More questions remain.':''}}</p>
<article v-for="row in rows" :key="row.id" class="quality-row"><h3>{{row.paper}} · Q{{row.number}}</h3><p>{{row.status}} · {{row.reviewed?'Current review recorded':'Not reviewed on this version'}} · {{row.solution_status||'No solution'}}</p><ul><li v-for="flag in row.flags" :key="flag">{{flag}}</li></ul><div class="quality-actions"><button class="btn btn-light" :disabled="busy" @click="run(()=>inspect(row))">Review question / solution</button><button class="btn btn-light" :disabled="busy" @click="emit('edit',row.id)">Edit / repair</button><button class="btn btn-light" :disabled="busy" @click="run(()=>visibility(row))">{{row.status==='HIDDEN'?'Restore':'Hide question'}}</button><a :href="'/api/papers/'+row.paper_id+'/source'" target="_blank" rel="noopener">Original PDF</a></div>
<section v-if="detail?.id===row.id" class="quality-detail"><QuestionContent :text="[detail.question.passage,detail.question.text].filter(Boolean).join('\n\n')" :images="detail.question.images.filter(i=>!i.option_key)"/><section v-for="o in detail.question.options" :key="o.key"><strong>{{o.key}}.</strong><QuestionContent :text="o.text" :images="detail.question.images.filter(i=>i.option_key===o.key)"/></section><h4>Source key</h4><pre>{{detail.question.answers}}</pre><h4>Solution preview</h4><MathText v-if="detail.solution" :text="detail.solution"/><p v-else>No solution uploaded.</p><form @submit.prevent="run(reviewed)"><label v-for="key in detail.checks" :key="key"><input type="checkbox" v-model="checks[key]" :disabled="busy"> {{labels[key]}}</label><button class="btn btn-primary" :disabled="busy||!detail.checks.every(k=>checks[k])">Record reviewed version</button></form></section></article><p v-if="!rows.length&&scanned&&!busy">No flags or unreviewed solutions in this batch. This does not guarantee all content is correct.</p></section></template>
<style scoped>.quality-panel details{margin-block:1rem}.quality-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:1rem;border:0;padding:0}.quality-panel label{display:block;margin:.8rem 0}.quality-panel select,.quality-panel textarea{display:block;width:100%;background:var(--bs-body-bg,#fff);color:inherit;border:1px solid var(--line,#94a3b8);padding:.6rem;border-radius:8px}.quality-panel textarea{min-height:90px}.quality-row{padding-block:1.2rem;border-bottom:1px solid #94a3b855}.quality-actions{display:flex;flex-wrap:wrap;gap:.6rem;align-items:center;margin-block:1rem}.quality-detail{padding:1rem;border:1px solid #94a3b855;border-radius:10px;margin-top:1rem}.quality-panel dd{overflow-wrap:anywhere}.quality-panel pre{white-space:pre-wrap}</style>
